```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    int minVal = tab[0], maxVal = tab[0];
    for (int i = 1; i < (int)tab.size(); i++) {
        if (tab[i] < minVal) minVal = tab[i];
        if (tab[i] > maxVal) maxVal = tab[i];
    }
    cout << "Minimum: " << minVal << endl;
    cout << "Maksimum: " << maxVal << endl;
    cout << "Rozstep: " << maxVal - minVal << endl;
    return 0;
}
```

**Wyjasnienie**: Klasyczny skan liniowy po min i max. Rozstep to po prostu max - min.

